import CrudPage from '../../components/ui/CrudPage';
import { branchApi } from '../../api/services';
import { Input } from '../../components/ui';

const columns = [
  { key: 'name', label: 'Name' },
  { key: 'code', label: 'Code' },
  { key: 'city', label: 'City' },
  { key: 'country', label: 'Country' },
];

function FormFields({ register, errors }) {
  return (
    <>
      <Input label="Name" error={errors.name?.message} {...register('name', { required: 'Required' })} />
      <Input label="Code" error={errors.code?.message} {...register('code', { required: 'Required' })} />
      <Input label="City" {...register('city')} />
      <Input label="Country" {...register('country')} />
      <Input label="Address" {...register('address')} />
    </>
  );
}

export default function BranchesPage() {
  return (
    <CrudPage
      queryKey="branches"
      api={branchApi}
      columns={columns}
      FormFields={FormFields}
      entityName="Branch"
    />
  );
}
